#requires -Version 5.1
[CmdletBinding()]
param([string]$RecoveryDirectory='', [string]$OutputDirectory=(Join-Path $HOME 'Downloads'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$app=Join-Path $env:LOCALAPPDATA 'StockRecommendationEngine'
$port=[int]((Get-Content -LiteralPath (Join-Path $app 'runtime-port.txt') | Select-Object -First 1).Trim())
if($port -lt 1 -or $port -gt 65535){throw 'Invalid actual runtime port. Open the existing SRE GUI normally.'}
if(-not $RecoveryDirectory){
 $runs=@(Get-ChildItem -LiteralPath (Join-Path $HOME 'Downloads') -Directory -Filter 'SRE-Windows-Continuation-*' | Where-Object {(Test-Path (Join-Path $_.FullName 'publication.json')) -and (Test-Path (Join-Path $_.FullName '2026-10-19-recovery.json'))} | Sort-Object Name)
 if(-not $runs.Count){throw 'Preserved recovery directory not found. Supply -RecoveryDirectory with the original continuation run directory.'}
 $RecoveryDirectory=$runs[0].FullName
}
$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory)
if($OutputDirectory.StartsWith($app,[StringComparison]::OrdinalIgnoreCase)){throw 'Output must be outside application data.'}
$run=Join-Path $OutputDirectory ('SRE-GUI-Replay-Identity-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6))
New-Item -ItemType Directory -Path $run -Force | Out-Null
$helper=Join-Path $run 'inspect-live.py'
[IO.File]::WriteAllBytes($helper,[Convert]::FromBase64String(''))
try{
 # Read-only process identity. No process is started, stopped or modified.
 try{
  $listeners=@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction Stop)
  $processes=@(foreach($listener in $listeners){Get-CimInstance Win32_Process -Filter "ProcessId=$($listener.OwningProcess)" | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath})
  $processes | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $run 'gui-process.json') -Encoding UTF8
 }catch{$_ | Out-String | Set-Content -LiteralPath (Join-Path $run 'process-inventory-unavailable.txt')}
 $py=Get-Command py.exe -ErrorAction SilentlyContinue
 if($py){& $py.Source -3 $helper --base "http://127.0.0.1:$port" --recovery $RecoveryDirectory --output $run *> (Join-Path $run 'inspection.log')}
 else{& python.exe $helper --base "http://127.0.0.1:$port" --recovery $RecoveryDirectory --output $run *> (Join-Path $run 'inspection.log')}
 if($LASTEXITCODE -ne 0){throw 'Inspection incomplete; see ERROR.txt and inspection.log. No replay was run or changed.'}
 Write-Host "Inspection complete: $run\COMPARISON.json"
}finally{
 $zip=$run+'.zip';Compress-Archive -LiteralPath $run -DestinationPath $zip
 Write-Host "PRIVATE REPORT: $zip"
}
